func testRenegociacaoDocumentoToOneSetOpRotinaContabilUsingRoc(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a RenegociacaoDocumento
	var b, c RotinaContabil

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, renegociacaoDocumentoDBTypes, false, strmangle.SetComplement(renegociacaoDocumentoPrimaryKeyColumns, renegociacaoDocumentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, rotinaContabilDBTypes, false, strmangle.SetComplement(rotinaContabilPrimaryKeyColumns, rotinaContabilColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, rotinaContabilDBTypes, false, strmangle.SetComplement(rotinaContabilPrimaryKeyColumns, rotinaContabilColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*RotinaContabil{&b, &c} {
		err = a.SetRoc(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Roc != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.RocRenegociacaoDocumentos[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if !queries.Equal(a.RocID, x.RocID) {
			t.Error("foreign key was wrong value", a.RocID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.RocID))
		reflect.Indirect(reflect.ValueOf(&a.RocID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if !queries.Equal(a.RocID, x.RocID) {
			t.Error("foreign key was wrong value", a.RocID, x.RocID)
		}
	}
}

